# bash completion for hephaestus                           -*- shell-script -*-
#
# Generated by `hephaestus completion bash`. Load it with
#   source <(hephaestus completion bash)
# or install it as a bash-completion file named "hephaestus".
# Candidates come from `hephaestus __complete`, which only reads the
# command's flag definitions. Works with bash 3.2 and later; does not need
# the bash-completion package.

_hephaestus() {
    local i w n
    # Rejoin "--flag=value", which bash splits at "=" (COMP_WORDBREAKS).
    local -a words=()
    for ((i = 0; i <= COMP_CWORD; i++)); do
        w=${COMP_WORDS[i]}
        n=${#words[@]}
        if ((n > 1)) && { [[ $w == "=" ]] || [[ ${COMP_WORDS[i-1]} == "=" ]]; }; then
            words[n-1]=${words[n-1]}$w
        else
            words[n]=$w
        fi
    done
    # The cursor may be inside a word: complete what is before it.
    local cur=${words[${#words[@]}-1]}
    local bashcur=${COMP_WORDS[COMP_CWORD]}
    [[ $bashcur == "=" ]] && bashcur=
    local strip=${cur%"$bashcur"}

    local out
    out=$("${COMP_WORDS[0]}" __complete "${words[@]:1}" 2>/dev/null) || return 0
    local directive=${out##*:}
    out=${out%:*}

    COMPREPLY=()
    if [[ $directive == 2 ]]; then
        local value=$cur pre=
        if [[ $cur == -*=* ]]; then
            value=${cur#*=}
            pre=${cur%"$value"}
        fi
        # bash 4+: compopt quotes the names; bash 3.2 has no compopt, so
        # they are quoted here.
        local quote=1
        type compopt >/dev/null 2>&1 && compopt -o filenames && quote=0
        while IFS= read -r w; do
            w=$pre$w
            w=${w#"$strip"}
            ((quote)) && w=$(printf '%q' "$w")
            COMPREPLY[${#COMPREPLY[@]}]=$w
        done < <(compgen -f -- "$value")
        return 0
    fi
    while IFS= read -r w; do
        [[ -z $w ]] && continue
        w=${w%%$'\t'*}
        COMPREPLY[${#COMPREPLY[@]}]=${w#"$strip"}
    done <<<"$out"
    return 0
}

complete -F _hephaestus hephaestus
